def pubmed_search_pubmed_key_words(key_words, num_results=10, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0052000" if __import__("os").path.isdir("./environment_mix/0052000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _log(status, detail=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            t1 = datetime.datetime.utcnow()
            row = {
                "id": f"req_{t1.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "endpoint": "pubmed_search_pubmed_key_words",
                "status": status,
                "timestamp": t1.replace(microsecond=0).isoformat() + "Z",
                "latency_ms": int((t1 - t0).total_seconds() * 1000),
            }
            if detail is not None:
                row["detail"] = detail
            logs.append(row)
            _save("request_log.json", logs)
        except Exception:
            pass

    if not isinstance(key_words, str):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "key_words must be a string.")
    if key_words.strip() == "":
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "key_words is required and must not be empty.")
    if not isinstance(num_results, int):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "num_results must be an integer.")
    if num_results <= 0:
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "num_results must be a positive integer.")

    store = _load("pubmed.json")
    if not isinstance(store, list):
        store = []
    terms = [t for t in (key_words or "").replace(",", " ").lower().split() if t.strip()]

    matches = []
    for row in store:
        if not isinstance(row, dict):
            continue
        arts = row.get("articles")
        if not isinstance(arts, list):
            continue
        for a in arts:
            if not isinstance(a, dict):
                continue
            title = a.get("title") or ""
            abstract = a.get("abstract") or ""
            kws = a.get("keywords")
            if not isinstance(kws, list):
                kws = []
            hay = (str(title) + " " + str(abstract) + " " + " ".join(str(x) for x in kws)).lower()
            if terms and not all(t in hay for t in terms):
                continue
            matches.append(
                {
                    "pmid": str(a.get("pmid", "")),
                    "title": a.get("title"),
                    "journal": a.get("journal"),
                    "year": a.get("year"),
                }
            )

    matches = [m for m in matches if m.get("pmid")]
    matches.sort(key=lambda x: (str(x.get("year") or ""), str(x.get("pmid") or "")), reverse=True)
    out = matches[:num_results]

    resp = {
        "query": {"key_words": key_words, "num_results": num_results},
        "total": len(matches),
        "count": len(out),
        "articles": out,
    }
    _log("ok", {"count": len(out), "total": len(matches)})
    return resp

def pubmed_search_pubmed_advanced(term=None, title=None, author=None, journal=None, start_date=None, end_date=None, num_results=10, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0052000" if __import__("os").path.isdir("./environment_mix/0052000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _log(status, detail=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            t1 = datetime.datetime.utcnow()
            row = {
                "id": f"req_{t1.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "endpoint": "pubmed_search_pubmed_advanced",
                "status": status,
                "timestamp": t1.replace(microsecond=0).isoformat() + "Z",
                "latency_ms": int((t1 - t0).total_seconds() * 1000),
            }
            if detail is not None:
                row["detail"] = detail
            logs.append(row)
            _save("request_log.json", logs)
        except Exception:
            pass

    def _is_str_or_none(x):
        return x is None or isinstance(x, str)

    if not _is_str_or_none(term) or not _is_str_or_none(title) or not _is_str_or_none(author) or not _is_str_or_none(journal):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "term/title/author/journal must be strings or null.")

    if not _is_str_or_none(start_date) or not _is_str_or_none(end_date):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "start_date/end_date must be strings or null.")

    if not isinstance(num_results, int):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "num_results must be an integer.")
    if num_results <= 0:
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "num_results must be a positive integer.")

    def _parse_date(s):
        if s is None:
            return None
        ss = s.strip()
        if ss == "":
            return None
        # Accept YYYY, YYYY-MM, YYYY-MM-DD
        try:
            if len(ss) == 4 and ss.isdigit():
                return datetime.date(int(ss), 1, 1)
            if len(ss) == 7:
                return datetime.datetime.strptime(ss, "%Y-%m").date()
            return datetime.datetime.strptime(ss, "%Y-%m-%d").date()
        except ValueError:
            return "BAD"

    sd = _parse_date(start_date)
    ed = _parse_date(end_date)
    if sd == "BAD" or ed == "BAD":
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Malformed date. Use YYYY, YYYY-MM, or YYYY-MM-DD.")
    if sd and ed and ed < sd:
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "end_date must be on or after start_date.")

    def _nonempty(s):
        return isinstance(s, str) and s.strip() != ""

    if not any(_nonempty(x) for x in (term, title, author, journal)):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Provide at least one of term, title, author, or journal.")

    store = _load("pubmed.json")
    if not isinstance(store, list):
        store = []

    term_l = term.strip().lower() if _nonempty(term) else None
    title_l = title.strip().lower() if _nonempty(title) else None
    author_l = author.strip().lower() if _nonempty(author) else None
    journal_l = journal.strip().lower() if _nonempty(journal) else None

    matches = []
    for row in store:
        if not isinstance(row, dict):
            continue
        arts = row.get("articles")
        if not isinstance(arts, list):
            continue
        for a in arts:
            if not isinstance(a, dict):
                continue

            a_title = str(a.get("title") or "")
            a_journal = str(a.get("journal") or "")
            a_authors = a.get("authors")
            if not isinstance(a_authors, list):
                a_authors = []
            a_year = str(a.get("year") or "")

            if term_l:
                blob = json.dumps(a, ensure_ascii=False).lower()
                if term_l not in blob:
                    continue
            if title_l and title_l not in a_title.lower():
                continue
            if journal_l and journal_l not in a_journal.lower():
                continue
            if author_l:
                if not any(author_l in str(au).lower() for au in a_authors):
                    continue

            # Date filter uses year field from schema (2019-2023); interpret as Jan 1 of that year
            if a_year.isdigit():
                try:
                    ay = datetime.date(int(a_year), 1, 1)
                except ValueError:
                    ay = None
            else:
                ay = None
            if sd and ay and ay < sd.replace(month=1, day=1):
                continue
            if ed and ay and ay > ed.replace(month=1, day=1):
                continue

            matches.append(
                {
                    "pmid": str(a.get("pmid", "")),
                    "title": a.get("title"),
                    "journal": a.get("journal"),
                    "year": a.get("year"),
                }
            )

    matches = [m for m in matches if m.get("pmid")]
    matches.sort(key=lambda x: (str(x.get("year") or ""), str(x.get("pmid") or "")), reverse=True)
    out = matches[:num_results]

    resp = {
        "query": {
            "term": term,
            "title": title,
            "author": author,
            "journal": journal,
            "start_date": start_date,
            "end_date": end_date,
            "num_results": num_results,
        },
        "total": len(matches),
        "count": len(out),
        "articles": out,
    }
    _log("ok", {"count": len(out), "total": len(matches)})
    return resp

def pubmed_get_pubmed_article_metadata(pmid, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0052000" if __import__("os").path.isdir("./environment_mix/0052000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _log(status, detail=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            t1 = datetime.datetime.utcnow()
            row = {
                "id": f"req_{t1.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "endpoint": "pubmed_get_pubmed_article_metadata",
                "status": status,
                "timestamp": t1.replace(microsecond=0).isoformat() + "Z",
                "latency_ms": int((t1 - t0).total_seconds() * 1000),
            }
            if detail is not None:
                row["detail"] = detail
            logs.append(row)
            _save("request_log.json", logs)
        except Exception:
            pass

    if pmid is None:
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "pmid is required.")

    if isinstance(pmid, int):
        pmid_s = str(pmid)
    elif isinstance(pmid, str):
        pmid_s = pmid.strip()
    else:
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "pmid must be a string or integer.")

    if pmid_s == "" or not pmid_s.isdigit():
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "pmid must be a valid PubMed identifier (digits only).", pmid=pmid_s)

    store = _load("pubmed.json")
    if not isinstance(store, list):
        store = []

    found = None
    for row in store:
        if not isinstance(row, dict):
            continue
        arts = row.get("articles")
        if not isinstance(arts, list):
            continue
        for a in arts:
            if isinstance(a, dict) and str(a.get("pmid", "")).strip() == pmid_s:
                found = a
                break
        if found:
            break

    if not found:
        _log("error", {"code": "NOT_FOUND", "pmid": pmid_s})
        return _err("NOT_FOUND", "pmid does not resolve to a stored article.", pmid=pmid_s)

    resp = {"pmid": pmid_s, "metadata": found}
    _log("ok", {"pmid": pmid_s})
    return resp

